package dev.arabicgames.update;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.view.*;import android.widget.*;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;import java.util.regex.*;

/** Same-package, same-signature APK updates from this repository's release assets only. */
public final class UpdateActivity extends Activity {
 static final String REPOSITORY="Tariq-220/ArabicGamesTranslator", API="https://api.github.com/repos/"+REPOSITORY+"/releases?per_page=20";
 private static volatile boolean playSession;
 public static void setPlaySessionActive(boolean active){playSession=active;}
 private static final ExecutorService WORK=Executors.newSingleThreadExecutor();private static volatile boolean working;private static volatile String message="";private static volatile File prepared;
 private final Handler ui=new Handler(Looper.getMainLooper());private TextView status;private String flavor;
 static final class Asset {final String name,url,digest,version;final long size;Asset(String n,String u,String h,String v,long s){name=n;url=u;digest=h;version=v;size=s;}}
 static int compare(String a,String b){String[] x=a.split("\\."),y=b.split("\\.");for(int i=0;i<3;i++){int d=Integer.compare(Integer.parseInt(x[i]),Integer.parseInt(y[i]));if(d!=0)return d;}return 0;}
 static Asset choose(JSONArray releases,String flavor,String current)throws Exception {
  if(!flavor.equals("Phone")&&!flavor.equals("TV"))throw new IOException("Invalid platform");
  Pattern pattern=Pattern.compile("^ArabicGames-"+flavor+"-(\\d+\\.\\d+\\.\\d+)"+(flavor.equals("Phone")?"-arm64":"")+"\\.apk$");Asset newest=null;
  for(int i=0;i<releases.length();i++){JSONObject release=releases.getJSONObject(i);if(release.optBoolean("draft")||release.optBoolean("prerelease"))continue;String tag=release.getString("tag_name");if(!tag.matches("[a-zA-Z0-9._-]{1,80}"))continue;
   JSONArray assets=release.getJSONArray("assets");for(int j=0;j<assets.length();j++){JSONObject a=assets.getJSONObject(j);String name=a.getString("name");Matcher m=pattern.matcher(name);if(!m.matches())continue;String version=m.group(1);if(compare(version,current)<=0||newest!=null&&compare(version,newest.version)<=0)continue;
    String digest=a.optString("digest"),url=a.getString("browser_download_url");long size=a.getLong("size");if(!digest.matches("sha256:[0-9a-fA-F]{64}")||size<1||size>250_000_000||!url.equals("https://github.com/"+REPOSITORY+"/releases/download/"+tag+"/"+name))throw new IOException("بيانات تحديث غير موثوقة.");newest=new Asset(name,url,digest.substring(7).toLowerCase(Locale.ROOT),version,size);
  }}return newest;
 }
 private static boolean allowed(URL u){return u.getProtocol().equals("https")&&(u.getPort()==-1||u.getPort()==443)&&u.getUserInfo()==null&&Arrays.asList("api.github.com","github.com","release-assets.githubusercontent.com","objects.githubusercontent.com").contains(u.getHost());}
 private static HttpURLConnection connect(String address)throws Exception {URL u=new URL(address);for(int r=0;r<6;r++){if(!allowed(u))throw new IOException("مصدر تحديث غير مسموح.");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","ArabicGames-Updater/1");c.setRequestProperty("Accept-Encoding","identity");int status=c.getResponseCode();if(status>=300&&status<400){String next=c.getHeaderField("Location");c.disconnect();if(next==null)throw new IOException("Invalid redirect");u=new URL(u,next);continue;}if(status!=200){c.disconnect();throw new IOException("HTTP "+status);}return c;}throw new IOException("Too many redirects");}
 private static Asset check(Context c,String flavor)throws Exception {HttpURLConnection connection=connect(API);try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2_000_000)throw new IOException("بيانات إصدار كبيرة.");out.write(b,0,n);}return choose(new JSONArray(out.toString("UTF-8")),flavor,c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName);}finally{connection.disconnect();}}
 private static String hash(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static void verifyPackage(Context c,File apk)throws Exception {
  PackageManager pm=c.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;
  PackageInfo next=pm.getPackageArchiveInfo(apk.getAbsolutePath(),flags),current=pm.getPackageInfo(c.getPackageName(),flags);
  if(next==null||!next.packageName.equals(c.getPackageName())||(Build.VERSION.SDK_INT>=28?next.getLongVersionCode()<=current.getLongVersionCode():next.versionCode<=current.versionCode))throw new IOException("التحديث لا يطابق التطبيق أو ليس أحدث.");
  Signature[] before=Build.VERSION.SDK_INT>=28?current.signingInfo.getApkContentsSigners():current.signatures,after=Build.VERSION.SDK_INT>=28?next.signingInfo.getApkContentsSigners():next.signatures;
  if(before==null||after==null||before.length!=after.length||before.length==0)throw new IOException("توقيع تحديث غير مطابق.");Set<String> existing=new HashSet<>();for(Signature s:before)existing.add(hash(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));for(Signature s:after)if(!existing.remove(hash(MessageDigest.getInstance("SHA-256").digest(s.toByteArray()))))throw new IOException("توقيع تحديث غير مطابق.");
 }
 private static File download(Context c,Asset asset)throws Exception {
  File folder=new File(c.getCacheDir(),"updates");if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("تعذر إنشاء مجلد التحديث.");File part=new File(folder,"update.part"),apk=new File(folder,asset.name);if(folder.getUsableSpace()<asset.size+20_000_000)throw new IOException("المساحة لا تكفي للتحديث.");HttpURLConnection connection=connect(asset.url);
  try {MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] b=new byte[65536];long count=0;int n;while((n=in.read(b))!=-1){if(playSession)throw new InterruptedIOException("التنزيل مؤجل حتى تنتهي جلسة اللعب.");count+=n;if(count>asset.size)throw new IOException("حجم التحديث غير مطابق.");out.write(b,0,n);digest.update(b,0,n);message="تنزيل "+asset.version+" · "+(count*100/asset.size)+"٪";}if(count!=asset.size||!hash(digest.digest()).equals(asset.digest))throw new IOException("فشل التحقق من التحديث.");}
   verifyPackage(c,part);java.nio.file.Files.move(part.toPath(),apk.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);return apk;
  }finally{connection.disconnect();part.delete();}
 }
 public static void onLaunch(Activity activity,String flavor){Context app=activity.getApplicationContext();android.content.SharedPreferences prefs=app.getSharedPreferences("updates",0);if(playSession||!prefs.getBoolean("automatic",true)||System.currentTimeMillis()-prefs.getLong("checked",0)<12*60*60*1000L||working)return;
  working=true;WORK.execute(()->{try{Asset asset=check(app,flavor);prefs.edit().putLong("checked",System.currentTimeMillis()).apply();if(asset!=null&&!playSession){prepared=download(app,asset);message="التحديث "+asset.version+" جاهز للتثبيت من صفحة التحديثات.";activity.runOnUiThread(()->{if(!activity.isFinishing()&&!activity.isDestroyed())new AlertDialog.Builder(activity).setTitle("تحديث جاهز").setMessage(message).setPositiveButton("فتح التحديث",(d,w)->activity.startActivity(new Intent(activity,UpdateActivity.class))).setNegativeButton("لاحقًا",null).show();});}}catch(Exception e){message="تعذر فحص التحديث؛ حاول من صفحة التحديثات.";}finally{working=false;}});
 }
 private final Runnable refresh=new Runnable(){public void run(){status.setText(message);ui.postDelayed(this,600);}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);flavor=getPackageName().endsWith(".tv")?"TV":"Phone";LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,28,28,28);root.setBackgroundColor(0xff142033);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);
  text(root,"تحديث التطبيق",25);try{text(root,"نسختك: "+getPackageManager().getPackageInfo(getPackageName(),0).versionName+" · "+flavor,17);}catch(Exception ignored){}text(root,"التحديث يحافظ على الإعدادات والمفاتيح والنماذج. ينزّل ملف جهازك فقط من مستودعنا، ويفحص البصمة وتوقيع التطبيق. أندرويد يطلب الموافقة قبل التثبيت.",16);
  CheckBox auto=new CheckBox(this);auto.setText("فحص وتنزيل التحديث تلقائيًا عند فتح التطبيق");auto.setTextColor(-1);auto.setChecked(getSharedPreferences("updates",0).getBoolean("automatic",true));auto.setOnCheckedChangeListener((v,on)->getSharedPreferences("updates",0).edit().putBoolean("automatic",on).apply());root.addView(auto);
  button(root,"فحص وتنزيل أحدث تحديث",()->{if(working)return;working=true;message="فحص الإصدارات…";Context app=getApplicationContext();WORK.execute(()->{try{Asset asset=check(app,flavor);if(asset==null)message="نسختك محدثة؛ لا يوجد إصدار أحدث لجهازك.";else{prepared=download(app,asset);message="تم تنزيل "+asset.version+" والتحقق منه. اضغط تثبيت التحديث.";}}catch(Exception e){message=e instanceof IOException?"تعذر التحديث: "+e.getMessage():"تعذر فحص التحديث. أعد المحاولة لاحقًا.";}finally{working=false;}});});
  button(root,"تثبيت التحديث المحفوظ",this::install);button(root,"كل الإصدارات والملفات المنفصلة ↗",()->{try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/"+REPOSITORY+"/releases")));}catch(ActivityNotFoundException e){message="لا يوجد متصفح؛ افتح صفحة مستودعنا من جهاز آخر.";}});status=text(root,message,16);button(root,"رجوع",this::finish);ScrollView scroll=new ScrollView(this);scroll.setPadding(0,40,0,30);scroll.addView(root);setContentView(scroll);}
 private TextView text(LinearLayout root,String value,int size){TextView view=new TextView(this);view.setText(value);view.setTextColor(-1);view.setTextSize(size);view.setPadding(8,10,8,10);root.addView(view);return view;}
 private void button(LinearLayout root,String label,Runnable task){Button b=new Button(this);b.setText(label);b.setMinHeight(56);b.setOnClickListener(v->task.run());root.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 private void install(){File apk=prepared;if(apk==null||!apk.isFile()){message="اضغط فحص وتنزيل التحديث أولًا.";return;}if(!getPackageManager().canRequestPackageInstalls()){try{startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,android.net.Uri.parse("package:"+getPackageName())));message="اسمح لهذا التطبيق بتثبيت تحديثه ثم ارجع واضغط تثبيت.";}catch(ActivityNotFoundException e){message="اسمح بتثبيت التطبيقات من إعدادات التلفزيون أو الجوال.";}return;}
  try{verifyPackage(this,apk);PackageInstaller installer=getPackageManager().getPackageInstaller();PackageInstaller.SessionParams params=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(getPackageName());int id=installer.createSession(params);
   try(PackageInstaller.Session session=installer.openSession(id)){try(InputStream in=new FileInputStream(apk);OutputStream out=session.openWrite("base.apk",0,apk.length())){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);session.fsync(out);}Intent callback=new Intent(this,InstallResultActivity.class);PendingIntent pending=PendingIntent.getActivity(this,id,callback,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0));session.commit(pending.getIntentSender());}message="انتظر نافذة أندرويد ووافق على تحديث التطبيق.";
  }catch(Exception e){message="تعذر تثبيت التحديث؛ لم تتغير النسخة الحالية.";}}
 @Override protected void onResume(){super.onResume();ui.post(refresh);}
 @Override protected void onPause(){ui.removeCallbacks(refresh);super.onPause();}
}
